// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
        // initialize must be invoked via low-level call because its parameters use
        // interface types declared inside the C source file (IERC20, IRewardRouterV2, IGlpManager).
        // glpManager needs a vault() getter, so a tiny stub is used for that argument.
        GlpManagerStub glp = new GlpManagerStub();
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                DnGmxBatchingManager.initialize.selector,
                address(0),
                address(0),
                address(0),
                address(glp),
                address(1),
                address(1)
            )
        );
        require(ok, "initialize failed");
    }

    function testFuzz_property(address newKeeper) public {
        vm.assume(newKeeper != address(0));

        // General rule: the owner (the account that initialized C) can always
        // set a new keeper, and c.keeper() then returns that address.
        bool success = true;
        try c.setKeeper(newKeeper) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success && c.keeper() == newKeeper);
    }
}

contract GlpManagerStub {
    function vault() external pure returns (address) {
        return address(1);
    }
}
